// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("flatRate charges the same for every parcel, at scale 2", () -> {
        var flat = flatRate(d("4.9"));
        eq(flat.cost(parcel("0.1", "10")).toPlainString(), "4.90");
        eq(flat.cost(parcel("30", "999")).toPlainString(), "4.90");
    });
    test("byWeight rounds the weight up to whole kilograms", () -> {
        var heavy = byWeight(d("3.00"), d("0"));
        eq(heavy.cost(parcel("2.1", "10")).toPlainString(), "9.00");
        eq(heavy.cost(parcel("2.0", "10")).toPlainString(), "6.00");
        eq(heavy.cost(parcel("2.4", "10")).toPlainString(), "9.00");
    });
    test("byWeight never charges less than the minimum", () ->
        eq(byWeight(d("3.00"), d("5")).cost(parcel("0.2", "10")).toPlainString(), "5.00"));
    test("freeOver is free from the limit up, inclusive", () -> {
        var promo = freeOver(d("50"), flatRate(d("4.99")));
        eq(promo.cost(parcel("1", "50.00")).toPlainString(), "0.00");
        eq(promo.cost(parcel("1", "120")).toPlainString(), "0.00");
        eq(promo.cost(parcel("1", "49.99")).toPlainString(), "4.99");
    });
    test("cheapest picks the lowest cost per parcel and needs an option", () -> {
        var best = cheapest(List.of(flatRate(d("7.50")), byWeight(d("2.00"), d("3.00"))));
        eq(best.cost(parcel("1.5", "10")), d("4.00"));
        eq(best.cost(parcel("5", "10")), d("7.50"));
        raises(IllegalArgumentException.class, () -> cheapest(List.of()));
    });
    test("Checkout quotes a named option and rejects unknown or duplicate names", () -> {
        var checkout = new Checkout();
        checkout.register("standard", flatRate(d("4.99")));
        eq(checkout.quote("standard", parcel("1", "10")), d("4.99"));
        var e = raises(IllegalArgumentException.class, () -> checkout.quote("drone", parcel("1", "10")));
        eq(e.getMessage(), "unknown shipping option: drone");
        raises(IllegalArgumentException.class, () -> checkout.register("standard", flatRate(d("1"))));
    });
    test("quoteAll lists every option in registration order", () -> {
        var checkout = new Checkout();
        checkout.register("pickup", flatRate(d("0")));
        checkout.register("standard", flatRate(d("4.99")));
        checkout.register("express", byWeight(d("6"), d("9")));
        checkout.register("budget", freeOver(d("30"), flatRate(d("2.50"))));
        var quotes = checkout.quoteAll(parcel("2.2", "20"));
        eq(new ArrayList<>(quotes.keySet()), List.of("pickup", "standard", "express", "budget"));
        eq(new ArrayList<>(quotes.values()), List.of(d("0.00"), d("4.99"), d("18.00"), d("2.50")));
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("defaults: GET, no headers, no body, a 30 second timeout", () -> {
        var r = request("https://api.example.org/orders").build();
        eq(r.method(), "GET");
        eq(r.headers(), Map.of());
        eq(r.body(), Optional.empty());
        eq(r.timeout(), Duration.ofSeconds(30));
    });
    test("method is upper-cased and checked", () -> {
        eq(request("http://x.io").method("post").body("{}").build().method(), "POST");
        raises(IllegalArgumentException.class, () -> request("http://x.io").method("FETCH"));
    });
    test("header names are case-insensitive and values build up in order", () -> {
        var r = request("https://x.io").header("Accept", "a").header("ACCEPT", "b").header("X-Id", "7").build();
        eq(r.headers(), Map.of("accept", List.of("a", "b"), "x-id", List.of("7")));
    });
    test("build refuses a body on GET or HEAD, and a url that is not http", () -> {
        var e = raises(IllegalStateException.class, () -> request("https://x.io").body("{}").build());
        eq(e.getMessage(), "GET cannot have a body");
        raises(IllegalStateException.class, () -> request("https://x.io").method("HEAD").body("x").build());
        raises(IllegalStateException.class, () -> request("ftp://x.io").build());
        eq(request("https://x.io").method("DELETE").body("why").build().body(), Optional.of("why"));
    });
    test("a timeout that is not positive fails at once", () -> {
        raises(IllegalArgumentException.class, () -> request("https://x.io").timeout(Duration.ZERO));
        raises(IllegalArgumentException.class, () -> request("https://x.io").timeout(Duration.ofSeconds(-1)));
        eq(request("https://x.io").timeout(Duration.ofMillis(250)).build().timeout(), Duration.ofMillis(250));
    });
    test("a built request is immutable, header lists included", () -> {
        var r = request("https://x.io").header("accept", "a").build();
        raises(UnsupportedOperationException.class, () -> r.headers().put("x", List.of()));
        raises(UnsupportedOperationException.class, () -> r.headers().get("accept").add("b"));
    });
    test("changing the builder after build never changes the built request", () -> {
        var b = request("https://x.io").header("accept", "a");
        var first = b.build();
        b.header("accept", "b").header("x-new", "1");
        eq(first.headers(), Map.of("accept", List.of("a")));
        eq(b.build().headers().get("accept"), List.of("a", "b"));
    });
    test("toBuilder copies a request so it can be varied", () -> {
        var get = request("https://x.io/items").header("accept", "json").timeout(Duration.ofSeconds(5)).build();
        var post = get.toBuilder().method("POST").header("accept", "xml").body("{}").build();
        eq(post.headers(), Map.of("accept", List.of("json", "xml")));
        eq(post.timeout(), Duration.ofSeconds(5));
        eq(post.url(), "https://x.io/items");
        eq(get.headers(), Map.of("accept", List.of("json")));
        eq(get.method(), "GET");
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("email accepts one @ with text on both sides", () -> {
        eq(email("ana@example.org"), new EmailNotifier("ana@example.org"));
        var e = raises(IllegalArgumentException.class, () -> email("ana"));
        eq(e.getMessage(), "bad email: ana");
        raises(IllegalArgumentException.class, () -> email("a@b@c"));
        raises(IllegalArgumentException.class, () -> email("@example.org"));
        raises(IllegalArgumentException.class, () -> email("ana@"));
    });
    test("sms needs + and 7 to 15 digits; slack needs # and a lower-case name", () -> {
        eq(sms("+4712345678"), new SmsNotifier("+4712345678"));
        raises(IllegalArgumentException.class, () -> sms("4712345678"));
        raises(IllegalArgumentException.class, () -> sms("+123456"));
        eq(sms("+123456789012345"), new SmsNotifier("+123456789012345"));
        raises(IllegalArgumentException.class, () -> sms("+1234567890123456"));
        eq(slack("#ops-alerts"), new SlackNotifier("#ops-alerts"));
        raises(IllegalArgumentException.class, () -> slack("#Ops"));
        raises(IllegalArgumentException.class, () -> slack("#"));
    });
    test("create picks the maker by scheme, case-insensitively", () -> {
        var f = NotifierFactory.withDefaults();
        eq(f.create("EMAIL:ana@x.org"), new EmailNotifier("ana@x.org"));
        eq(f.create("SLACK:#ops"), new SlackNotifier("#ops"));
        eq(f.create("sms:+4712345678"), new SmsNotifier("+4712345678"));
    });
    test("create passes everything after the FIRST colon to the maker", () -> {
        var f = new NotifierFactory();
        f.register("echo", target -> message -> target + " <- " + message);
        eq(f.create("echo:a:b").send("hi"), "a:b <- hi");
    });
    test("an unknown scheme names the known ones, sorted", () -> {
        var f = NotifierFactory.withDefaults();
        var e = raises(IllegalArgumentException.class, () -> f.create("fax:+4712345678"));
        eq(e.getMessage(), "unknown scheme 'fax'; known: email, slack, sms");
    });
    test("a uri without a colon is rejected, and bad targets still fail", () -> {
        var f = NotifierFactory.withDefaults();
        var e = raises(IllegalArgumentException.class, () -> f.create("ana@x.org"));
        eq(e.getMessage(), "not a notifier uri: ana@x.org");
        raises(IllegalArgumentException.class, () -> f.create("sms:12"));
    });
    test("registering a scheme twice is an error, in any letter case", () -> {
        var f = NotifierFactory.withDefaults();
        raises(IllegalStateException.class, () -> f.register("Email", Exercise::email));
    });
    test("callers see only Notifier: send works the same for every channel", () -> {
        var f = NotifierFactory.withDefaults();
        var sent = new ArrayList<String>();
        for (var uri : List.of("email:ops@x.org", "sms:+4799999999", "slack:#oncall")) sent.add(f.create(uri).send("disk full"));
        eq(sent, List.of("email to ops@x.org: disk full", "sms to +4799999999: disk full", "slack #oncall: disk full"));
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

