public static void main(String[] args) {
    test("an approved charge returns the bank's reference", () -> {
        var bank = new LegacyBankApi("OK|REF-778");
        eq(new BankAdapter(bank, ACCOUNTS).charge("c2", d("9.99"), "GBP"), new PaymentResult(true, "REF-778", null));
    });
    test("the request carries the account, whole cents and an upper-case currency", () -> {
        var bank = new LegacyBankApi("OK|R1", "OK|R2", "OK|R3", "OK|R4");
        var gateway = new BankAdapter(bank, ACCOUNTS);
        gateway.charge("c1", d("12.5"), "eur");
        gateway.charge("c1", d("12.500"), "EUR");
        gateway.charge("c2", d("1000"), "usd");
        gateway.charge("c2", d("4.35"), "Gbp");
        eq(bank.requests, List.of("ACCT=NO-1;CENTS=1250;CUR=EUR", "ACCT=NO-1;CENTS=1250;CUR=EUR",
            "ACCT=GB-22;CENTS=100000;CUR=USD", "ACCT=GB-22;CENTS=435;CUR=GBP"));
    });
    test("decline codes become readable reasons", () -> {
        var gateway = new BankAdapter(new LegacyBankApi("ERR|51", "ERR|54", "ERR|05"), ACCOUNTS);
        eq(gateway.charge("c1", d("5"), "EUR"), new PaymentResult(false, null, "insufficient funds"));
        eq(gateway.charge("c1", d("5"), "EUR"), new PaymentResult(false, null, "expired card"));
        eq(gateway.charge("c1", d("5"), "EUR"), new PaymentResult(false, null, "declined (code 05)"));
    });
    test("a reply of unknown shape is an IllegalStateException, not a decline", () -> {
        var gateway = new BankAdapter(new LegacyBankApi("HELLO", "OK|", "ERR|"), ACCOUNTS);
        var e = raises(IllegalStateException.class, () -> gateway.charge("c1", d("5"), "EUR"));
        eq(e.getMessage(), "unexpected bank response: HELLO");
        raises(IllegalStateException.class, () -> gateway.charge("c1", d("5"), "EUR"));
        raises(IllegalStateException.class, () -> gateway.charge("c1", d("5"), "EUR"));
    });
    test("an unknown customer is rejected before calling the bank", () -> {
        var bank = new LegacyBankApi("OK|R1");
        var e = raises(IllegalArgumentException.class, () -> new BankAdapter(bank, ACCOUNTS).charge("c9", d("5"), "EUR"));
        eq(e.getMessage(), "unknown customer: c9");
        eq(bank.requests, List.of());
    });
    test("amounts must be positive with at most two decimals", () -> {
        var bank = new LegacyBankApi("OK|R1");
        var gateway = new BankAdapter(bank, ACCOUNTS);
        raises(IllegalArgumentException.class, () -> gateway.charge("c1", d("0"), "EUR"));
        raises(IllegalArgumentException.class, () -> gateway.charge("c1", d("-3"), "EUR"));
        raises(IllegalArgumentException.class, () -> gateway.charge("c1", d("1.005"), "EUR"));
        eq(bank.requests, List.of());
    });
    test("only USD, EUR and GBP are accepted", () -> {
        var bank = new LegacyBankApi("OK|R1");
        var gateway = new BankAdapter(bank, ACCOUNTS);
        raises(IllegalArgumentException.class, () -> gateway.charge("c1", d("5"), "JPY"));
        eq(bank.requests, List.of());
        eq(gateway.charge("c1", d("5"), "gbp").approved(), true);
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("CSV writes header, rows and totals, each ending in CRLF", () ->
        eq(new CsvExporter().export(SALES),
            "item,qty,amount\r\nbolt,3,2.50\r\nnut,10,0.33\r\nwasher,1,4.00\r\nTOTAL,14,6.83\r\n"));
    test("CSV quotes an item holding a comma, a quote or a line break", () -> {
        var rows = List.of(new Row("5\" bolt, zinc", 1, BigDecimal.ONE), new Row("two\nlines", 2, BigDecimal.TEN),
            new Row("cr\rhere", 0, BigDecimal.ZERO));
        eq(new CsvExporter().export(rows),
            "item,qty,amount\r\n\"5\"\" bolt, zinc\",1,1.00\r\n\"two\nlines\",2,10.00\r\n\"cr\rhere\",0,0.00\r\nTOTAL,3,11.00\r\n");
    });
    test("amounts round half up to two decimals", () -> {
        var rows = List.of(new Row("a", 1, new BigDecimal("0.005")), new Row("b", 1, new BigDecimal("0.004")));
        eq(new CsvExporter().export(rows), "item,qty,amount\r\na,1,0.01\r\nb,1,0.00\r\nTOTAL,2,0.01\r\n");
    });
    test("Markdown keeps the default line end and writes a table", () ->
        eq(new MarkdownExporter().export(SALES.subList(0, 1)),
            "| item | qty | amount |\n| --- | ---: | ---: |\n| bolt | 3 | 2.50 |\n| **total** | 3 | 2.50 |\n"));
    test("Markdown escapes a pipe inside an item", () ->
        eq(new MarkdownExporter().export(List.of(new Row("in|out", 2, BigDecimal.ONE))),
            "| item | qty | amount |\n| --- | ---: | ---: |\n| in\\|out | 2 | 1.00 |\n| **total** | 2 | 1.00 |\n"));
    test("an empty report still has its header and a zero total", () -> {
        eq(new CsvExporter().export(List.of()), "item,qty,amount\r\nTOTAL,0,0.00\r\n");
        eq(exportWith(csvFormat(), List.of()), "item,qty,amount\r\nTOTAL,0,0.00\r\n");
    });
    test("csvFormat built from parts matches the template byte for byte", () -> {
        var tricky = new ArrayList<>(SALES);
        tricky.add(new Row("say \"hi\"", 4, new BigDecimal("1.255")));
        eq(exportWith(csvFormat(), tricky), new CsvExporter().export(tricky));
    });
    test("a new format by composition needs no subclass", () -> {
        var plain = new ExportFormat("ITEMS", Row::item, rows -> rows.size() + " rows", "\n");
        eq(exportWith(plain, SALES), "ITEMS\nbolt\nnut\nwasher\n3 rows\n");
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("run executes a command and undo restores the cart", () -> {
        var cart = new Cart();
        var h = new History(cart);
        h.run(new AddItem("A", 2));
        h.run(new AddItem("A", 3));
        eq(cart.snapshot(), Map.of("A", 5));
        ok(h.undo());
        eq(cart.snapshot(), Map.of("A", 2));
        ok(h.undo());
        eq(cart.snapshot(), Map.of());
    });
    test("undo and redo walk back and forth, and say false when there is nothing", () -> {
        var cart = new Cart();
        var h = new History(cart);
        ok(!h.undo());
        ok(!h.redo());
        h.run(new AddItem("A", 1));
        h.run(new SetQuantity("A", 5));
        ok(h.undo());
        eq(cart.qty("A"), 1);
        ok(h.redo());
        eq(cart.qty("A"), 5);
        ok(!h.redo());
    });
    test("running a new command clears the redo stack", () -> {
        var cart = new Cart();
        var h = new History(cart);
        h.run(new AddItem("A", 1));
        h.undo();
        h.run(new AddItem("B", 1));
        ok(!h.redo());
        eq(cart.snapshot(), Map.of("B", 1));
    });
    test("RemoveItem and SetQuantity restore exactly what they replaced", () -> {
        var cart = new Cart();
        var h = new History(cart);
        h.run(new AddItem("A", 7));
        h.run(new RemoveItem("A"));
        eq(cart.has("A"), false);
        h.undo();
        eq(cart.qty("A"), 7);
        h.run(new SetQuantity("A", 0));
        eq(cart.has("A"), false);
        h.undo();
        eq(cart.qty("A"), 7);
        h.run(new SetQuantity("N", 3));
        h.undo();
        eq(cart.has("N"), false);
    });
    test("a command that throws changes nothing and is not recorded", () -> {
        var cart = new Cart();
        var h = new History(cart);
        h.run(new AddItem("A", 1));
        raises(IllegalStateException.class, () -> h.run(new RemoveItem("ghost")));
        raises(IllegalArgumentException.class, () -> h.run(new AddItem("A", 0)));
        raises(IllegalArgumentException.class, () -> h.run(new SetQuantity("A", -2)));
        eq(h.log(), List.of("add 1 x A"));
        eq(cart.snapshot(), Map.of("A", 1));
    });
    test("a macro is all or nothing: a failing step rolls back the earlier ones", () -> {
        var cart = new Cart();
        var h = new History(cart);
        h.run(new AddItem("A", 1));
        var bad = new Macro(List.of(new AddItem("A", 2), new SetQuantity("A", 9), new AddItem("B", 2), new RemoveItem("ghost")));
        raises(IllegalStateException.class, () -> h.run(bad));
        eq(cart.snapshot(), Map.of("A", 1));
        eq(h.log(), List.of("add 1 x A"));
    });
    test("a macro is undone newest step first, as one history entry", () -> {
        var cart = new Cart();
        var h = new History(cart);
        h.run(new Macro(List.of(new AddItem("A", 1), new SetQuantity("A", 5), new AddItem("B", 2))));
        eq(cart.snapshot(), Map.of("A", 5, "B", 2));
        ok(h.undo());
        eq(cart.snapshot(), Map.of());
        ok(!h.undo());
    });
    test("log describes the undo stack, oldest first", () -> {
        var cart = new Cart();
        var h = new History(cart);
        h.run(new AddItem("A1", 2));
        h.run(new SetQuantity("A1", 5));
        h.run(new Macro(List.of(new AddItem("B", 1), new RemoveItem("A1"))));
        eq(h.log(), List.of("add 2 x A1", "set A1 to 5", "macro(add 1 x B, remove A1)"));
        h.undo();
        eq(h.log(), List.of("add 2 x A1", "set A1 to 5"));
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

